 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    row_stats = []
    for r in range(h):
        c, n = Counter(grid[r]).most_common(1)[0]
        row_stats.append((c, n / w))
    col_stats = []
    for j in range(w):
        c, n = Counter(grid[r][j] for r in range(h)).most_common(1)[0]
        col_stats.append((c, n / h))
    threshold = 0.80
    colors = {c for c,p in row_stats + col_stats if p > threshold}
    def score(color):
        rr = [p for c,p in row_stats if c == color and p > threshold]
        cc = [p for c,p in col_stats if c == color and p > threshold]
        if not rr or not cc:
            return (-1, -1, -1)
        # Separator color has the most uniform stripes, across both axes.
        return (min(sum(rr)/len(rr), sum(cc)/len(cc)), len(rr)+len(cc), min(len(rr),len(cc)))
    line = max(colors, key=score)
    rs = [i for i,(c,p) in enumerate(row_stats) if c == line and p > threshold]
    cs = [j for j,(c,p) in enumerate(col_stats) if c == line and p > threshold]
    marks = [(ri, cj, grid[r][c]) for ri,r in enumerate(rs) for cj,c in enumerate(cs) if grid[r][c] != line]
    if not marks:
        return [[line]]
    r0, r1 = min(a for a,b,v in marks), max(a for a,b,v in marks)
    c0, c1 = min(b for a,b,v in marks), max(b for a,b,v in marks)
    fill = Counter(v for row in grid for v in row if v != line).most_common(1)[0][0]
    out = []
    for i in range(r0, r1):
        row = []
        for j in range(c0, c1):
            vals = [grid[rs[i]][cs[j]], grid[rs[i]][cs[j+1]],
                    grid[rs[i+1]][cs[j]], grid[rs[i+1]][cs[j+1]]]
            row.append(vals[0] if vals[0] != line and len(set(vals)) == 1 else fill)
        out.append(row)
    return out
